describe('Filter Clearing Functionality', () => {
    beforeEach(() => {
        cy.visit('/search'); // Adjust the URL to your application's search page
        // Apply some filters to test clearing functionality
        cy.get('[data-testid="filter-category"]').select('Electronics');
        cy.get('[data-testid="filter-price"]').type('100');
        cy.get('[data-testid="filter-brand"]').check('BrandA');
        cy.get('[data-testid="apply-filters"]').click();
    });

    it('should clear all applied filters successfully', () => {
        cy.get('[data-testid="clear-filters"]').click();
        cy.get('[data-testid="filter-category"]').should('have.value', '');
        cy.get('[data-testid="filter-price"]').should('be.empty');
        cy.get('[data-testid="filter-brand"]').should('not.be.checked');
    });

    it('should not display any filters after clearing', () => {
        cy.get('[data-testid="clear-filters"]').click();
        cy.get('[data-testid="active-filters"]').should('not.exist');
    });
});
